<!-- This file is generated by AI. -->
<!--
  预览面板: 引擎站点嵌在 iframe 里, 左侧栏顶部常驻。

  **iframe 靠换 key 强制重挂** —— 引擎启动状态是一次性的, 直接改 src 在跨源场景下不保证重走
  完整启动流程。**16:9 横向画布**: 引擎在竖屏 iframe 内会把画面旋转 90°, 所以
  `preview-frame-wrap`(黑底 + 居中) → `preview-frame-box`(aspect-ratio 16/9) → iframe 两层都不能省。
  **静音走三条路** (`previewClient.setMuted` 写宿主状态、`postMessage` 通知已打开的页面、后端注入
  脚本兜底), 只做一条就会"打开时还是响的"或"拨了开关不生效"; `previewMuted` 刻意不进站点注册的
  依赖, 否则拨一次静音就整站重载。**全屏授权写在 iframe 的 `allow` 上** —— 跨源 iframe 默认拿不到
  fullscreen, 引擎因此干脆不画全屏按钮。
-->
<script lang="ts">
  import { getCurrentWindow } from '@tauri-apps/api/window';
  import { openUrl } from '@tauri-apps/plugin-opener';
  import { untrack } from 'svelte';

  import { createPreviewOutputSettingsMessage } from '../preview/audio-bridge';
  import { previewClient } from '../preview/client';
  import {
    applyPreviewFullscreenAction,
    previewFullscreenTransition,
    type PreviewFullscreenStatus,
  } from '../preview/fullscreen';
  import { createId, EDITOR_PREVIEW_PROTOCOL_V1_SUBPROTOCOL, SESSION_REGISTER_PREVIEW_TYPE } from '../preview/protocol';
  import { actions, appStore } from '../state/store.svelte';
  import Button from './Button.svelte';
  import Switch from './Switch.svelte';

  /*
   * 引擎侧的握手类型 (postMessage), 名字由**引擎**定: 引擎启动后喊 `BOOTSTRAP_REQUEST`, 编辑器回
   * `BOOTSTRAP_PROVIDE` + `embeddedLaunchId`; 引擎再带这个 id 去 `/api/webgalsync` 注册, 网关据此
   * 把它与编辑器会话配成一对 (`service/preview/sync.rs` 按 `embedded_launch_id` 查找)。
   * **配不上的后果是静默的**: sync-scene 没有收件人, 预览不跳转、工具条一直显示"未连接"。
   *
   * 两种请求都答: `SESSION_REGISTER_PREVIEW_TYPE` 是**编辑器 ↔ 网关**之间的 WebSocket 注册类型,
   * 与引擎 ↔ 父窗口的 postMessage 协议是两回事; 引擎不在本仓库, 无法确定它只说哪一种, 两种请求
   * 类型不同、互不冲突, 各回各的 envelope。
   */
  const BOOTSTRAP_REQUEST = 'webgal.preview.bootstrap.request';
  const BOOTSTRAP_PROVIDE = 'webgal.preview.bootstrap.provide';

  let frame: { url: string; key: string } | null = $state(null);
  let error = $state<string | null>(null);
  let iframe: HTMLIFrameElement | undefined = $state();

  /** 最近一次嵌入启动 id —— 与 iframe 内的引擎会话配对。 */
  let launchId = createId();

  /**
   * 进入全屏前窗口是不是最大化。
   *
   * 只有 `fullscreenchange` 回调读它, 因此是普通变量而不是 `$state`。
   */
  let windowWasMaximized = false;
  let fullscreen: PreviewFullscreenStatus = { mirrored: false, corrected: false };

  const muted = $derived(appStore.settings.previewMuted);
  const ready = $derived(appStore.previewReady);
  const autoSync = $derived(appStore.settings.autoSyncPreview);

  /** 项目用哪个引擎: 项目绑定 → 引擎列表里的那一个 (与 `lib/engine` 的口径一致)。 */
  function resolveEnginePath(): string | undefined {
    const projectPath = appStore.projectPath;
    if (!projectPath) return undefined;
    const binding = Object.entries(appStore.projectBindings).find(
      ([key]) => key.replace(/\\/g, '/').toLowerCase() === projectPath.replace(/\\/g, '/').toLowerCase()
    )?.[1];
    return appStore.settings.engines.find((engine) => engine.id === binding?.engineId)?.path;
  }

  /*
   * 站点注册: 项目或引擎变化时重挂 iframe。
   *
   * `cancelled` 是必需的: 切项目时上一个 `ensureSite` 可能还在 await, 不加守卫就会用旧项目的
   * url 覆盖新项目的 iframe。
   *
   * 这里**不能**调 `resetSite()`: 这个 effect 会因为"任何设置变化"重跑 (它读了 `settings.engines`),
   * 在此重置会让拨一次静音就整站重载。换项目能拿到正确站点靠的是 `ensureSite` **按 项目+引擎
   * 记账**的缓存 (见 `preview/client.ts`)。
   */
  $effect(() => {
    const projectPath = appStore.projectPath;
    const enginePath = resolveEnginePath();
    if (!projectPath) {
      frame = null;
      return;
    }

    let cancelled = false;
    void (async () => {
      try {
        const url = await previewClient.ensureSite(projectPath, enginePath);
        if (cancelled) return;
        if (!url) {
          error = '预览服务器启动失败';
          return;
        }
        error = null;
        const id = createId();
        await previewClient.bindEmbeddedLaunchId(id);
        if (cancelled) return;
        launchId = id;
        frame = { url, key: id };
      } catch (e) {
        if (!cancelled) error = String(e);
      }
    })();

    return () => {
      cancelled = true;
    };
  });

  /*
   * 刷新: 换 key 重挂 iframe。
   *
   * `untrack` 不是装饰: `reload()` 会读 `frame` 再写 `frame`, 而它是在 effect 体内同步调用的,
   * 于是 `frame` 会成为这个 effect 的依赖 —— 写一次就再跑一次, 变成"永远在重挂 iframe"的死循环。
   */
  $effect(() => {
    const token = appStore.previewReloadToken;
    if (token === 0) return;
    untrack(() => reload());
  });

  function reload(): void {
    if (!frame) return;
    const id = createId();
    launchId = id;
    void previewClient.bindEmbeddedLaunchId(id);
    // 换 key 而不是改 src: 强制 iframe 完整重挂
    frame = { url: frame.url, key: id };
  }

  /**
   * 静音开关: 同时写宿主状态 (给之后打开的页面) 与通知当前页面。
   *
   * 现取 `muted` 而不是捕获闭包, 于是这个 effect 不依赖 `muted`, 也不会因为拨开关而重挂 iframe。
   */
  $effect(() => {
    void previewClient.setMuted(muted);
  });

  /** 页面重挂 / 刚连上 / 拨了开关, 都要把当前静音状态推给它。 */
  $effect(() => {
    const current = frame;
    void ready;
    postMuted(
      untrack(() => muted),
      current !== null
    );
  });

  function postMuted(value: boolean, hasFrame: boolean): void {
    if (!hasFrame) return;
    const win = iframe?.contentWindow;
    if (!win) return;
    win.postMessage(createPreviewOutputSettingsMessage(value), '*');
  }

  /**
   * 引擎侧发起握手: 校验来源是同一个 iframe 再回应。
   *
   * effect 体内没有同步的响应式读取 (读取都在回调里), 因此只在挂载时注册一次监听。
   */
  $effect(() => {
    const onMessage = (event: MessageEvent) => {
      const target = iframe?.contentWindow;
      if (!target || event.source !== target) return;
      const data = event.data as { type?: string; protocol?: string } | null;
      if (!data || typeof data !== 'object') return;

      const embeddedLaunchId = launchId;

      // 开发期记录握手: 引擎有没有来要 id、我们回了什么
      if (import.meta.env.DEV && (data.type === BOOTSTRAP_REQUEST || data.type === SESSION_REGISTER_PREVIEW_TYPE)) {
        console.debug('[preview] 引擎握手请求', data.type, '→ 回应 embeddedLaunchId', embeddedLaunchId);
      }

      // 平铺格式的那条: 引擎只认这个形状
      if (data.type === BOOTSTRAP_REQUEST) {
        target.postMessage({ type: BOOTSTRAP_PROVIDE, embeddedLaunchId }, '*');
        return;
      }

      // 新 envelope: 与网关的 V1 协议同名, 兜住按新协议实现的引擎版本
      if (data.type === SESSION_REGISTER_PREVIEW_TYPE) {
        target.postMessage(
          {
            protocol: EDITOR_PREVIEW_PROTOCOL_V1_SUBPROTOCOL,
            type: 'session.registered',
            id: createId(),
            payload: { embeddedLaunchId },
          },
          '*'
        );
      }
    };

    window.addEventListener('message', onMessage);
    return () => window.removeEventListener('message', onMessage);
  });

  /*
   * 全屏: 引擎底栏画不画"全屏"按钮取决于它页面里的 `document.fullscreenEnabled`, 授权写在 iframe 的
   * `allow` 属性上; 这里负责授权之后的**窗口侧**处理。
   *
   * Windows 上 Tauri 自己会把"webview 里有全屏元素"映射成窗口全屏, 所以下面的动作大多是幂等的
   * 重复调用; 真正要补的是"最大化窗口 + 无边框全屏"那个组合 —— tao 不清最大化状态, 底部会留下
   * 一条任务栏高的黑边。折算与执行都在 `preview/fullscreen` 里 (纯函数, 有单测钉住顺序)。
   */
  $effect(() => {
    const win = getCurrentWindow();

    /*
     * 只在**不在全屏**时记录窗口形态: 全屏那一次的 resize 正是我们要修的形态变化, 不能拿它当
     * "用户想要的窗口样子"。它也可能早于 `fullscreenchange` 到达, 但那时窗口还停在最大化状态。
     */
    const syncWindowWasMaximized = () => {
      if (document.fullscreenElement !== null) return;
      void win
        .isMaximized()
        .then((value) => {
          windowWasMaximized = value;
        })
        .catch(() => {
          // 问不到窗口形态 (例如前端跑在浏览器里) 就当作不是最大化, 不影响预览本身
        });
    };

    const onFullscreenChange = () => {
      // 只管"预览 iframe 自己"成了全屏元素的情况 (顶层文档里别的元素全屏与我们无关)
      const fullscreenElement = document.fullscreenElement;
      const active = fullscreenElement !== null && fullscreenElement === iframe;
      const next = previewFullscreenTransition(fullscreen, {
        fullscreenActive: active,
        windowWasMaximized,
      });
      fullscreen = { mirrored: next.mirrored, corrected: next.corrected };
      void applyPreviewFullscreenAction(win, next.action).catch((err) => {
        // 窗口侧失败不该影响预览本身: 元素全屏照常生效, 只是窗口形态可能不对
        console.error('预览全屏补正失败', err);
      });
    };

    // 先取一次, 之后靠 resize 跟上 (打开/关闭项目都会改窗口形态, 见 lib/window.ts)
    syncWindowWasMaximized();
    const unlistenResize = win.onResized(syncWindowWasMaximized);
    document.addEventListener('fullscreenchange', onFullscreenChange);
    return () => {
      document.removeEventListener('fullscreenchange', onFullscreenChange);
      void unlistenResize.then((off) => off());
      // 面板卸载会把 iframe 一起摘掉, 元素全屏随之结束, 而那次 fullscreenchange 我们未必还能听到
      if (fullscreen.corrected) {
        void applyPreviewFullscreenAction(win, { kind: 'restore-maximized' }).catch(() => {});
      }
    };
  });
</script>

<div class="preview-panel">
  <div class="preview-toolbar">
    <!--
      连接状态常显在最左: 它是"预览现在能不能用"的唯一指示, 藏起来只会让人以为预览坏了。
      不用 Spinner —— 未连接是常态 (没打开项目 / 服务器没起来), 不是加载中。
    -->
    <span class="preview-ready" class:ready>{ready ? '● 已连接' : '○ 未连接'}</span>
    <span class="preview-toolbar-spacer"></span>

    <!-- 「光标移动时同步预览」的总开关 (与设置页里的那一项是同一个值) -->
    <span class="preview-sync">
      <Switch
        checked={autoSync}
        label="预览"
        onchange={(value) => actions.updateSettings({ autoSyncPreview: value })}
      />
      <span class="preview-sync-label">预览</span>
    </span>

    <Button
      appearance="bare"
      iconSize={18}
      icon={muted ? 'SpeakerMute' : 'Speaker2'}
      title={muted ? '取消静音' : '静音预览'}
      onclick={() => actions.updateSettings({ previewMuted: !muted })}
    />
    <Button appearance="bare" iconSize={18} icon="ArrowClockwise" title="刷新预览" onclick={reload} />
    <Button
      appearance="bare"
      iconSize={18}
      icon="Open"
      title="在浏览器中打开预览"
      disabled={!frame}
      onclick={() => frame && void openUrl(frame.url)}
    />
  </div>

  <div class="preview-frame-wrap">
    {#if error}
      <p class="preview-error">{error}</p>
    {:else if frame}
      <!-- 16:9 画布: 横向比例由 `.preview-frame-box` 钉住 (`aspect-ratio: 16/9`), wrap 负责黑底与居中 -->
      <div class="preview-frame-box">
        {#key frame.key}
          <iframe
            bind:this={iframe}
            src={frame.url}
            class="preview-frame"
            title="WebGAL 预览"
            allow="autoplay; fullscreen"
            allowfullscreen
            onload={() =>
              postMuted(
                untrack(() => muted),
                true
              )}
          ></iframe>
        {/key}
      </div>
    {:else}
      <p class="preview-loading">正在启动预览…</p>
    {/if}
  </div>
</div>
